<?php
namespace App\Http\Controllers\Api\V1;
use App\Enums\AppointmentStatus; use App\Http\Controllers\Controller; use App\Http\Requests\StoreMedicalRecordRequest; use App\Http\Resources\MedicalRecordResource; use App\Http\Responses\ApiResponse; use App\Models\Appointment; use App\Models\MedicalRecord;
class MedicalRecordController extends Controller { public function store(StoreMedicalRecordRequest $r){ $a=Appointment::findOrFail($r->appointment_id); if($r->user()->doctor->id !== $a->doctor_id) return ApiResponse::error('Dokter hanya boleh mengisi pasien jadwalnya',403); $mr=MedicalRecord::create($r->validated()+['doctor_id'=>$r->user()->doctor->id]); $a->update(['status'=>AppointmentStatus::COMPLETED]); return ApiResponse::success(new MedicalRecordResource($mr),'Rekam medis dibuat',201); } public function show(MedicalRecord $medicalRecord){ $mr=$medicalRecord->load('appointment.patient.user','appointment.doctor.user'); $u=request()->user(); $ok=$u->isRole('admin') || $u->doctor?->id===$mr->doctor_id || $u->patient?->id===$mr->appointment->patient_id; if(!$ok) return ApiResponse::error('Forbidden',403); return ApiResponse::success(new MedicalRecordResource($mr)); } }
